if mibBuilder.loadTexts: ciscoSdslLineMIB.setDescription("This MIB module describes all variations of the symmetric \n        DSL line interfaces.  The structure of this module resembles \n        and maintains consistency with the ADSL-LINE-MIB, \n        ADSL-DMT-LINE-MIB, CISCO-ADSL-DMT-LINE-MIB, and \n        CISCO-ADSL-CAP-LINE-MIB. Observe that the tables in this \n        module do not necessarily extend the tables defined by the\n        these mibs. Currently, only those tables that contain \n        configuration information extend the profile tables defined \n        by the above modules.  This allows the management\n        client to define DSL configuration profiles that apply across\n        all DSL modems, independent of the technology being utilized by\n        the modem.\n\n        *** DEFINITIONS ***\n\n\tATTENUATION\n\t  Attenuation is a decrease in the strength of a signal \n\t  over the length of a cable.\n\n        CODING VIOLATION\n            A coding violation occurs when the incoming signal exhibits\n            a CRC anomaly.\n\n        DOWNSTREAM\n            The flow of data in the direction from the ATU-C to ATU-R.\n                      \n        ERRORED SECOND\n            A second with one or more coding violations or one or more\n            incoming defects (e.g., LOS or LOSQ).\n\n        LINE RATE\n            The total data rate supported by a line.  Observe that the\n            payload rate is equal the line rate for the earliest\n            implementations of SDSL.  However, the payload rate maybe\n            less than the line rate for future implementations.\n\n        LOSS OF SYNC DEFECT\n            A Loss of Sync Defect is defined as 3 consecutive received \n            frames which contain one or more errors in the framing\n            bits. A Loss of Sync Defect shall be cleared when at least \n            2 consecutive received frames contain no errors in the\n            framing bits.\n\n        LOSS OF SYNC FAILURE \n             A LOSW Failure is defined as at least 2 consecutive\n             seconds of LOSW Defect.  The LOSW Failure should be\n             cleared when the LOSW defect is absent for 20 seconds or\n             less. (i.e. clear within 20 seconds ).\n\n        MARGIN (also referred to as 'SNR margin')\n            The difference between the SNR of the received signal and\n            the SNR required to provide a BER of 10E-7.\n\n        SEVERELY ERRORED SECOND\n            A one second interval during which or more LOSW or CV defects\n            are declared. \n\n        UNAVAILABLE SECOND\n            A Unavailable Second is defined as a one second interval\n            during which LOSW Failure ( at least 2 seconds of LOSW\n            Defect ).\n\n        UPSTREAM\n            The flow of data in the direction from the ATU-R to ATU-C.\n\n        *** ABBREVIATIONS, ACRONYMS, AND SYMBOLS ***\n\n        ADSL - Asymmetric Digital Subscriber Line.\n\n        ATM - Asynchronous Transfer Mode.\n\n        BER - Bit Error Ratio.\n\n        CV - Coding Violation.\n\n        DSL - Digital Subscriber Line.\n\n        ES - Errored Second.\n\n        LOS - Loss Of Sync.\n\n        LOSQ - Loss Of Signal Quality.\n\n        LOSW - Loss of Sync Word Failure\n\n\tPSD - Power Spectral Density.\n\n        SES - Severely Errored Second.\n\n        SNR - Signal-to-Noise Ratio.\n\n        STM - Synchronous Transfer Mode.\n\n        STU-C - SDSL Transceiver Unit, Central Office end.\n\n        STU-R - ADSL Transceiver Unit, Remote terminal end.\n\n        UAS - UnAvailable Second.")
class SdslPerfTimeElapsed(TextualConvention, Gauge32):
    description = "The number of seconds that have elapsed since the beginning of\n        the current measurement period.  If, for some reason, such as an\n        adjustment in the system's time-of-day clock, the current\n        interval exceeds the maximum value, the agent will return the\n        maximum value."
    status = 'current'

class SdslPerfCurrDayCount(TextualConvention, Gauge32):
    description = "A counter associated with interval performance measurements in\n        a current 1-day (24 hour) measurement interval.\n\n        The value of this counter starts at zero at the beginning of an\n        interval and increases when associated events occur, until the\n        end of the 1-day interval.  At that time, the agent stores the\n        value of the counter in the previous 1-day history interval,\n        if available, and resets the value of the counter to zero.\n\n        In the case where the agent has no valid data available for this\n        interval, the corresponding object instance is not available.\n        In this case, the agent will respond with the appropriate error\n        indicating that the instance does not exist; that is,\n        'noSuchName' in response to a SNMPv1 get request, and\n        'noSuchInstance' in response to a SNMPv2 get request."
    status = 'current'

class SdslPerfPrevDayCount(TextualConvention, Gauge32):
    description = "A counter associated with interval performance measurements\n        during the most previous 1-day (24 hour) measurement interval.\n        The value of this counter is equal to the current day counter\n        at the end of its most recent interval.\n\n        In the case where the agent has no valid data available for this\n        interval, the corresponding object instance is not available.\n        In this case, the agent will respond with the appropriate error\n        indicating that the instance does not exist; that is,\n        'noSuchName' in response to a SNMPv1 get request, and\n        'noSuchInstance' in response to a SNMPv2 get request."
    status = 'current'

class SdslStuxDefect(TextualConvention, Bits):
    description = 'This object specifies any possible defects currently being\n        exhibited by the STU-x.  The value of this object is a bitmap\n        of possible defects.  The following list summarizes the\n        meaning of each bit in the bitmap\n\n        0   lossOfSignal            The STU-x is not receiving signal.\n\n        1   lossOfSignalQuality     The upstream SNR margin has fallen\n                                    below the SNR margin required to\n                                    maintain a minimum BER of 10^-7.\n\n        2   noPeerStuPresent        The STU-x can not initialize due\n                                    to the absence of a peer STU-x.\n\n        3   lossOfSyncFailure       The STU-x has suffered from at\n                                    least 2 consecutive seconds of\n                                    LOSW defect.'
    status = 'current'
    namedValues = NamedValues(("lossOfSignal", 0), ("lossOfSignalQuality", 1), ("noPeerStuPresent", 2), ("lossOfSyncFailure", 3))

